-- Du lieu mau: xoa toan bo tai khoan cu, tao QUANLY + 10 nhan vien + 20 khach hang,
-- them 50 mon an (MA0003-MA0052) va 50 nuoc uong (NU0001-NU0050), anh tai DuLieu/AnhMon/<ma>.jpg. Chay lai nhieu lan van an toan.
USE [QuanLyNhaHang_PBL2];
SET XACT_ABORT ON;
BEGIN TRAN;

DELETE FROM dbo.TaiKhoan;

DELETE FROM dbo.NhanVien WHERE ma IN (N'NV0001', N'NV0002', N'NV0003', N'NV0004', N'NV0005', N'NV0006', N'NV0007', N'NV0008', N'NV0009', N'NV0010');

DELETE FROM dbo.KhachHang WHERE ma IN (N'KH0001', N'KH0002', N'KH0003', N'KH0004', N'KH0005', N'KH0006', N'KH0007', N'KH0008', N'KH0009', N'KH0010', N'KH0011', N'KH0012', N'KH0013', N'KH0014', N'KH0015', N'KH0016', N'KH0017', N'KH0018', N'KH0019', N'KH0020');

-- Bo khoang trang thua o ten 2 mon cu.
UPDATE dbo.ThucDon SET ten = LTRIM(RTRIM(ten)) WHERE ma IN (N'MA0001', N'MA0002');
DELETE FROM dbo.ThucDon WHERE ma IN (N'MA0003', N'MA0004', N'MA0005', N'MA0006', N'MA0007', N'MA0008', N'MA0009', N'MA0010', N'MA0011', N'MA0012', N'MA0013', N'MA0014', N'MA0015', N'MA0016', N'MA0017', N'MA0018', N'MA0019', N'MA0020', N'MA0021', N'MA0022', N'MA0023', N'MA0024', N'MA0025', N'MA0026', N'MA0027', N'MA0028', N'MA0029', N'MA0030', N'MA0031', N'MA0032', N'MA0033', N'MA0034', N'MA0035', N'MA0036', N'MA0037', N'MA0038', N'MA0039', N'MA0040', N'MA0041', N'MA0042', N'MA0043', N'MA0044', N'MA0045', N'MA0046', N'MA0047', N'MA0048', N'MA0049', N'MA0050', N'MA0051', N'MA0052', N'NU0001', N'NU0002', N'NU0003', N'NU0004', N'NU0005', N'NU0006', N'NU0007', N'NU0008', N'NU0009', N'NU0010', N'NU0011', N'NU0012', N'NU0013', N'NU0014', N'NU0015', N'NU0016', N'NU0017', N'NU0018', N'NU0019', N'NU0020', N'NU0021', N'NU0022', N'NU0023', N'NU0024', N'NU0025', N'NU0026', N'NU0027', N'NU0028', N'NU0029', N'NU0030', N'NU0031', N'NU0032', N'NU0033', N'NU0034', N'NU0035', N'NU0036', N'NU0037', N'NU0038', N'NU0039', N'NU0040', N'NU0041', N'NU0042', N'NU0043', N'NU0044', N'NU0045', N'NU0046', N'NU0047', N'NU0048', N'NU0049', N'NU0050');

